    int minFlips(vector<vector<int>>& grid) {
        int m, n;
        m = n = 0;
        cnt1 = cnt2 = 0;
        for row in grid:
            for j in range(n // 2):
                if row[j]!= row[n - j - 1]:
                    cnt1 += 1
        for j in range(n):
            for i in range(m // 2):
                if grid[i][j]!= grid[m - i - 1][j]:
                    cnt2 += 1
        return min(cnt1, cnt2) // 2 * 2
    }

private:
    int cnt1;
    int cnt2;
};
