def get_string_between_two_patterns(string, pattern1, pattern2):
    pattern1 = re.compile(pattern1)
    pattern2 = re.compile(pattern2)
    match = pattern1.search(string)
    if match:
        start = match.end()
    else:
        return ''
    match = pattern2.search(string, start)
    if match:
        end = match.start()
    else:
        end = len(string)
    return string[start:end]
